using System;namespace Exoduser.UnityPort.Core {public sealed class GateEnterDelay {public bool Pending{get;private set;}public double Elapsed{get;private set;}public bool Ready=>Pending&&Elapsed>=1.1;public bool Begin(){if(Pending)return false;Pending=true;Elapsed=0;return true;}public void Tick(double delta){if(Pending&&delta>0&&!double.IsInfinity(delta)&&!double.IsNaN(delta))Elapsed+=delta;}public bool Consume(){if(!Ready)return false;Pending=false;return true;}public void Reset(){Pending=false;Elapsed=0;}}}